items.outputText:
{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목과 개선 방법을 연결하는 판단을 검증한다. 실행 계획과 조회 구조에서 확인한 사실을 근거로 인덱스 추가가 적절하다고 판단한 이유에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "운영 화면의 신고 목록 조회 쿼리에 응답 지연이 발생한 상황이다.",
          "task": "조회 병목에 인덱스 추가가 적절한 개선 방법인지 판단해야 했다.",
          "action": "실행 계획이나 조회 구조에서 확인한 병목을 조회 조건 및 인덱스의 역할과 연결해 판단 근거를 설명한다.",
          "result": "해당 병목에 인덱스 추가가 적절하다고 본 근거가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "인덱스 추가가 해당 조회 병목 개선에 적절하다고 판단한 근거",
          "실행 계획이나 조회 구조에서 실제 확인한 병목 관련 사실",
          "확인한 병목과 추가한 인덱스의 역할 사이의 구체적인 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요, 인덱스 추가가 병목 개선에 적절하다고 판단한 근거는 무엇이었어요?",
      "answerTip": "당시 경험을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인덱스 추가를 선택한 근거가 해당 조회 쿼리의 병목에 맞게 구체적으로 설명된다.",
            "실행 계획이나 조회 구조에서 실제 확인한 사실이 명확히 제시된다.",
            "확인한 병목이 추가한 인덱스로 줄어들 수 있는 이유를 논리적으로 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가의 근거와 병목 관련 사실을 제시하지만 설명이 일부 포괄적이다.",
            "확인한 병목과 인덱스의 역할을 연결하나 해당 쿼리에 대한 구체적인 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가했다는 사실만 말하고 선택 근거를 제시하지 못한다.",
            "실행 계획이나 조회 구조에서 확인한 병목 관련 사실이 드러나지 않는다.",
            "확인한 병목과 인덱스의 역할 사이의 연결이 없거나 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 오류의 원인을 로그로 추적하는 판단을 검증한다. 시간순 로그의 어떤 기록을 근거로 스케줄러 중복 실행으로 원인을 좁혔는지에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "배포 후 같은 알림이 두 번 발송된다는 문의가 들어온 상황이다.",
          "task": "알림 중복 발송의 원인을 실제 로그에 근거해 좁혀야 했다.",
          "action": "시간순으로 모은 로그에서 확인한 기록과 그 기록이 스케줄러 중복 실행을 가리킨다고 판단한 이유를 설명한다.",
          "result": "로그의 관찰 내용에서 스케줄러 중복 실행이라는 원인 판단으로 이어지는 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "로그를 근거로 알림 중복 발송의 원인을 스케줄러 중복 실행으로 좁힌 판단",
          "중복 실행 판단에 사용한 실제 로그 기록의 내용",
          "해당 로그 기록이 두 서버의 스케줄러 중복 실행을 뒷받침하는 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적하셨던데요, 시간순으로 모은 로그에서 무엇을 보고 스케줄러 중복 실행으로 원인을 좁히셨어요?",
      "answerTip": "기억에 남는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "원인을 스케줄러 중복 실행으로 좁힌 판단이 실제 로그 기록에 근거해 구체적으로 설명된다.",
            "판단에 사용한 로그 기록의 내용이 명확하게 제시된다.",
            "해당 기록이 두 서버의 스케줄러 중복 실행을 의미하는 이유를 논리적으로 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그에서 확인한 내용과 스케줄러 중복 실행이라는 판단을 제시하지만 기록의 구체성이 부족하다.",
            "로그 기록과 원인 판단의 연결은 확인되나 두 서버의 중복 실행을 뒷받침하는 설명이 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "스케줄러 중복 실행이라는 결론만 말하고 근거가 된 로그 기록을 제시하지 못한다.",
            "로그를 확인했다는 설명에 그쳐 실제 관찰 내용이 드러나지 않는다.",
            "제시한 로그 기록이 스케줄러 중복 실행이라는 판단을 뒷받침하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업 요청을 요구사항으로 구체화하는 판단을 검증한다. 세탁소 인터뷰 내용을 요구사항 정의서의 구현 범위로 정리한 기준 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 5곳의 인터뷰 내용을 바탕으로 예약 서비스의 요구사항 정의서를 작성한 상황이다.",
          "task": "요청의 목적을 파악하고 요구사항 정의서에 담을 구현 범위를 정해야 했다.",
          "action": "인터뷰에서 확인한 요청의 목적과 제약을 근거로 구현 범위를 구분한 기준을 설명한다.",
          "result": "그 기준에 따라 요구사항 정의서에서 포함하거나 제외한 범위가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "요구사항 정의서의 구현 범위를 정한 구체적인 기준",
          "해당 기준의 근거가 된 인터뷰 요청의 목적이나 제약",
          "그 근거와 기준이 실제 포함 또는 제외 결정으로 이어진 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 요청을 요구사항 정의서로 정리하셨던데요, 당시 구현 범위는 어떤 기준으로 정하셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "구현 범위를 정한 기준을 구체적으로 설명한다.",
            "인터뷰에서 확인한 요청의 목적이나 제약을 기준의 근거로 제시한다.",
            "제시한 근거와 기준이 실제 요구사항의 포함 또는 제외 결정으로 이어진 관계가 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "구현 범위를 정한 기준은 제시하지만 기준의 구체성이 부족하다.",
            "인터뷰 내용이나 범위 결정 사례를 제시하나, 해당 내용이 기준과 연결되는 설명은 일부 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "구현 범위의 판단 기준 없이 요구사항 정의서를 작성했다는 사실만 설명한다.",
            "인터뷰 요청의 목적이나 제약, 실제 범위 결정 사이의 연결을 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 구현 가능한 화면 흐름으로 구체화하는 설계 판단을 검증한다. 화면설계서에 담은 예외 상황 중 가장 고민한 설계 결정 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "예약·취소·알림 흐름과 예외 상황을 포함한 화면설계서 28장을 작성한 상황이다.",
          "task": "예외 상황에서 사용자가 보게 될 화면 상태와 이어지는 흐름을 구체화해야 했다.",
          "action": "가장 고민한 예외 상황 하나를 짚고, 해당 상황의 화면 상태와 흐름을 정한 결정 및 이유를 설명한다.",
          "result": "선택한 설계 결정이 화면설계서에 어떤 상태와 흐름으로 구체화되었는지 드러난다."
        },
        "expectedEvidence": [
          "예외 상황의 화면 흐름에서 가장 고민한 구체적인 설계 결정",
          "해당 결정이 필요했던 예외 발생 조건과 사용자 상황",
          "결정에 따라 화면설계서에 구체화한 화면 상태와 이어지는 흐름",
          "그 화면 흐름으로 설계한 이유와 예외 상황 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 예외 상황의 화면 흐름에서 가장 고민하신 설계 결정은 무엇이었어요?",
      "answerTip": "한 가지 사례에 집중해 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "가장 고민한 설계 결정을 특정 예외 상황의 화면 흐름으로 명확하게 제시한다.",
            "예외 발생 조건과 사용자 상황이 구체적으로 드러난다.",
            "화면설계서에 담은 화면 상태와 이어지는 흐름을 구현 내용을 이해할 수 있는 수준으로 설명한다.",
            "설계 이유가 해당 예외 상황과 논리적으로 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황과 관련된 설계 결정은 제시하지만 발생 조건이나 사용자 상황이 다소 모호하다.",
            "화면 상태와 흐름을 일부 설명하나, 구체적인 설계 내용이나 그 이유의 연결이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "화면설계서의 장수나 작성 도구만 언급하고 예외 상황에 대한 설계 결정을 제시하지 못한다.",
            "예외 발생 조건과 화면 상태 또는 흐름의 관계를 확인하기 어렵다.",
            "설계 이유가 제시한 예외 상황과 연결되지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방 용량의 이상을 확인한 경험에서, 확인되지 않은 처방대로 투약하지 않고 중단하기로 판단한 근거를 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 상황이다.",
          "task": "해당 처방대로 투약해도 되는지 판단해야 했다.",
          "action": "처방 용량과 평소 용량의 차이를 확인하고, 용량의 적절성이 확인되지 않았다는 근거로 투약 중단을 판단한 내용을 설명한다.",
          "result": "확인 전 투약을 멈추기로 한 판단과 그 근거의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "투약을 멈추기로 판단한 구체적인 근거",
          "처방 용량이 평소 용량의 두 배라는 차이를 인식한 내용",
          "용량 차이의 적절성이 확인되지 않아 처방대로 바로 투약할 수 없다고 판단한 연결"
        ]
      },
      "question": "푸른결종합병원에서 수술 후 환자의 진통제 처방이 평소 용량의 두 배였던 적이 있으셨는데요, 투약을 멈추기로 판단하신 근거는 뭐였어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "처방 용량과 평소 용량의 차이를 구체적으로 짚어 투약 중단의 근거를 설명한다.",
            "용량 차이의 적절성이 확인되지 않은 상태라는 점을 투약 중단 판단과 명확히 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 다른 처방 용량을 보고 투약을 멈췄다는 핵심 근거는 제시한다.",
            "용량 차이의 구체적인 내용이나 확인 전 투약을 중단해야 한다고 판단한 연결이 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단의 근거를 제시하지 못하거나 일반적인 투약 주의사항만 설명한다.",
            "처방 용량의 차이를 인식한 내용과 투약 중단 판단 사이의 연결이 확인되지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "일상적인 환자 관찰 기록 업무에서, 관찰한 내용을 근거로 상태 변화를 판단해 간호 기록에 남긴 기준을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 환자의 활력징후와 통증을 관찰하고 기록한 업무 상황이다.",
